    /// </response>
    /// <response code="422">
    /// <para>Validation Error</para>
    /// </response>
    public async Task PostPurchaseRetryAsync(
        PackageName? x_iap_packagename, SimpleReceiptSchema requestBody, 
        // Successful Response
        Action<ReceiptDetailSchema> on200 = null, 
        // Validation Error
        Action<HTTPValidationError> on422 = null, 
        Action<string> onError = null)
    {
        string url = $"{Url}/api/purchase/retry";
        using (var request = new UnityWebRequest(url, "POST"))
        {
            try
            {
            request.uri = new Uri(url);
            string headerValue = x_iap_packagename.ToString();
            if (PackageNameTypeConverter.InvalidEnumMapping.ContainsValue(headerValue))
            {
                headerValue = PackageNameTypeConverter.InvalidEnumMapping.First(kvp => kvp.Value == headerValue).Key;
            }
            request.SetRequestHeader("x-iap-packagename", headerValue);
            var bodyString = System.Text.Json.JsonSerializer.Serialize(requestBody);
            var jsonToSend = new UTF8Encoding().GetBytes(bodyString);
            request.uploadHandler = new UploadHandlerRaw(jsonToSend);
            request.uploadHandler.contentType = "application/json";
            request.downloadHandler = new DownloadHandlerBuffer();
            request.SetRequestHeader("accept", "application/json");
            request.SetRequestHeader("Content-Type", "application/json");
            request.timeout = 10;
            }
            catch (Exception ex)
            {
                onError(ex.Message);
                return;
            }
            try
            {
                await request.SendWebRequest();
                PostPurchaseRetryAsyncProcessResponse(request, on200, on422, onError);
            }
            catch (Exception ex)
            {
                PostPurchaseRetryAsyncProcessResponse(request, on200, on422, onError);
            }
        }
    }

